"""Run in Fusion: colored 200 x 150 x 10 mm plaque and two white rear feet.
Export bodies yourself with Save as Mesh > 3MF > Millimeter.
Artwork geometry and colors are embedded in this script; no assets folder is needed.
Mesh import files are temporary; the sidecar log is retained.
"""
from pathlib import Path
from contextlib import contextmanager
from collections import Counter
import array
import base64
import logging
import math
import struct
import sys
import tempfile
import time
import traceback
import zipfile
import zlib

WIDTH_MM = 200.0
HEIGHT_MM = 150.0
TOTAL_THICKNESS_MM = 10.0
RELIEF_MM = 3.0
BASE_EDGE_RADIUS_MM = 3.0
BASE_INDENT_DEPTH_MM = 0.25
ANGLE_DEG = 15.0
CHANNEL_CENTERS = (50.0, 150.0)
CHANNEL_START = 10.0
CHANNEL_END = 75.0
CHANNEL_DEPTH = 3.0
FOOT_TOP_EDGE_RADIUS_MM = .5
DOVETAIL_DEPTH_MM = CHANNEL_DEPTH - .1
PALETTE = (
    ('White', (255,255,255)), ('Black', (25,25,25)),
    ('Brown', (151,87,33)), ('Red', (210,25,35)), ('Green', (112,166,40)),
)
# Object-audited IDs: White, Black, Brown, Red, Green.
COLOR_REMAP = (0,1,2,3,4)
COLOR_MAP_REVISION = "chest-mouth-ear-cleanup-2026-10-09"
ROOT = Path(__file__).resolve().parent
LOG_PATH = ROOT/'CamelandPanda.log'


def groove_point(x, y):
    """Rear slot: 8 mm floor, 6 mm mouth, 9 mm loading bay at Y=10..36.

    A 0.25 mm surface strip describes each wall. The re-entrant wall creates
    dovetail retention without a boolean operation on the dense relief mesh.
    """
    t = max(0.0, min(1.0, (y-CHANNEL_START)/.25, (CHANNEL_END-y)/.25))
    if t == 0:
        return x, 0.0
    entry = max(0.0,min(1.0,(36.0-y)/.5))
    for center in CHANNEL_CENTERS:
        delta = x-center
        a = abs(delta)
        # The loading bay is wider than the full rail; open from the back.
        half = 4.0 + .5*entry
        if a <= half:
            return x, CHANNEL_DEPTH*t
        if a <= half+.25:
            fraction = (a-half)/.25
            mouth = 3.0*(1-entry)+(half+.25)*entry
            mapped = half+(mouth-half)*fraction
            return center+math.copysign(a+(mapped-a)*t,delta), CHANNEL_DEPTH*t*(1-fraction)
    return x, 0.0


def triangulate(poly):
    """Ear clipping for a simple CCW 2D polygon."""
    def cross(a,b,c):
        return (b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])
    ids=list(range(len(poly))); out=[]
    while len(ids)>3:
        for k,b in enumerate(ids):
            a,c=ids[k-1],ids[(k+1)%len(ids)]
            if cross(poly[a],poly[b],poly[c]) <= 1e-10:
                continue
            if any(all(cross(poly[u],poly[v],poly[q])>=-1e-10
                       for u,v in ((a,b),(b,c),(c,a)))
                   for q in ids if q not in (a,b,c)):
                continue
            out.append((a,b,c)); ids.pop(k); break
        else:
            raise ValueError('Cannot triangulate foot profile.')
    out.append(tuple(ids)); return out


def round_profile_corners(poly, corner_indices, radius, segments=8):
    """Replace selected convex profile corners with sampled circular arcs."""
    rounded = []
    tangent_distances = {}
    for i, corner in enumerate(poly):
        if i not in corner_indices:
            rounded.append(corner)
            continue
        previous = poly[i-1]
        following = poly[(i+1)%len(poly)]
        to_previous = (previous[0]-corner[0], previous[1]-corner[1])
        to_following = (following[0]-corner[0], following[1]-corner[1])
        previous_length = math.hypot(*to_previous)
        following_length = math.hypot(*to_following)
        u = (to_previous[0]/previous_length, to_previous[1]/previous_length)
        v = (to_following[0]/following_length, to_following[1]/following_length)
        angle = math.acos(max(-1.0, min(1.0, u[0]*v[0]+u[1]*v[1])))
        if not 0 < angle < math.pi:
            raise ValueError('Foot top edge requires a convex profile corner.')
        tangent = radius/math.tan(angle/2)
        if tangent >= min(previous_length, following_length):
            raise ValueError('Foot top edge radius does not fit its profile.')
        tangent_distances[i] = tangent
        start = (corner[0]+u[0]*tangent, corner[1]+u[1]*tangent)
        end = (corner[0]+v[0]*tangent, corner[1]+v[1]*tangent)
        bisector = (u[0]+v[0], u[1]+v[1])
        bisector_length = math.hypot(*bisector)
        center_distance = radius/math.sin(angle/2)
        center = (corner[0]+bisector[0]/bisector_length*center_distance,
                  corner[1]+bisector[1]/bisector_length*center_distance)
        start_angle = math.atan2(start[1]-center[1], start[0]-center[0])
        end_angle = math.atan2(end[1]-center[1], end[0]-center[0])
        incoming = (corner[0]-previous[0], corner[1]-previous[1])
        outgoing = (following[0]-corner[0], following[1]-corner[1])
        direction = 1 if incoming[0]*outgoing[1]-incoming[1]*outgoing[0] > 0 else -1
        sweep = (end_angle-start_angle) % (2*math.pi) if direction > 0 else -(
            (start_angle-end_angle) % (2*math.pi))
        for step in range(segments+1):
            if step == 0:
                rounded.append(start)
            elif step == segments:
                rounded.append(end)
            else:
                angle_at = start_angle+sweep*step/segments
                rounded.append((center[0]+radius*math.cos(angle_at),
                                center[1]+radius*math.sin(angle_at)))
    return rounded, tangent_distances


def table_height(base=7.0, radius=3.0):
    """Lowest point of the plaque's sampled lower round-over at a 15° lean.

    Use the same side-ring samples as CamelandPanda.mesh_triangles. The rear
    grooves start above this edge and the artwork does not reach the margin.
    """
    angle=math.radians(ANGLE_DEG)
    samples=[]
    for z in (0.,radius*.5,radius,base-radius,base-radius*.5,base):
        cy=radius
        cz=max(radius,min(z,base-radius))
        dy,dz=-cy,z-cz
        length=math.hypot(dy,dz)
        y=cy+dy*radius/length
        rz=cz+dz*radius/length
        samples.append(y*math.cos(angle)+rz*math.sin(angle))
    return min(samples)


def foot_triangles(center=0.0, base=7.0, radius=3.0):
    angle=math.radians(ANGLE_DEG); co,si=math.cos(angle),math.sin(angle)
    def yz(height, rear):
        return (height*co+rear*si, height*si-rear*co)
    # Rear-only sole on the SAME tabletop plane as the plaque's bottom edge.
    # The web sits against the plaque back at Z=0; only the dovetail enters it.
    ground=table_height(base,radius)
    profile=[(74.7,0.0),(35.3,0.0),yz(ground+4,8),
             yz(ground,8),yz(ground,65),yz(ground+4,65),(74.7,-4)]
    profile, top_tangents=round_profile_corners(
        profile,(0,1),FOOT_TOP_EDGE_RADIUS_MM)
    area=sum(a[0]*b[1]-b[0]*a[1] for a,b in zip(profile,profile[1:]+profile[:1]))
    if area<0: profile.reverse()
    rail_start=35.3+top_tangents[1]
    rail_end=74.7-top_tangents[0]
    def vertex(side,i): return (center+side*2.7,*profile[i])
    triangles=[]
    for a,b,c in triangulate(profile):
        triangles.extend([(vertex(1,a),vertex(1,b),vertex(1,c)),
                          (vertex(-1,c),vertex(-1,b),vertex(-1,a))])
    for i,a in enumerate(profile):
        j=(i+1)%len(profile); b=profile[j]
        if a[1]==b[1]==0.0:
            continue  # Internal web-to-dovetail contact face.
        triangles.extend([(vertex(-1,i),vertex(1,j),vertex(1,i)),
                          (vertex(-1,i),vertex(-1,j),vertex(1,j))])
    # XZ rail cross-section CCW, bottom edge omitted to join web.
    rail=[(-2.7,0.0),(2.7,0.0),(2.7,.3),(3.7,DOVETAIL_DEPTH_MM),
          (-3.7,DOVETAIL_DEPTH_MM),(-2.7,.3)]
    def rv(y,i): return (center+rail[i][0],y,rail[i][1])
    for a,b,c in triangulate(rail):
        triangles.extend([(rv(rail_start,a),rv(rail_start,b),rv(rail_start,c)),
                          (rv(rail_end,c),rv(rail_end,b),rv(rail_end,a))])
    for i in range(1,len(rail)):
        j=(i+1)%len(rail)
        triangles.extend([(rv(rail_start,i),rv(rail_end,i),rv(rail_end,j)),
                          (rv(rail_start,i),rv(rail_end,j),rv(rail_start,j))])
    return triangles

def load_heights():
    raw = zlib.decompress(base64.b85decode(RELIEF_DATA_B85))
    nx, ny = struct.unpack_from('<II', raw)
    if nx < 2 or ny < 2 or len(raw) != 8 + 2 * nx * ny:
        raise ValueError('Invalid relief height field.')
    values = array.array('H')
    values.frombytes(raw[8:])
    if sys.byteorder != 'little':
        values.byteswap()
    if max(values) != 65535:
        raise ValueError('Height field must reach the full raised-relief range.')
    return nx, ny, values


def mesh_triangles(nx, ny, values):
    """Closed relief with all twelve base edges rounded by a spherical offset."""
    base = TOTAL_THICKNESS_MM - RELIEF_MM
    radius = BASE_EDGE_RADIUS_MM
    if not 0 < radius < min(WIDTH_MM, HEIGHT_MM, base)/2:
        raise ValueError('Base edge radius must be positive and less than half the base thickness/size.')
    def rounded(x, y, z):
        p = (WIDTH_MM*x/(nx-1), HEIGHT_MM*y/(ny-1), z)
        core = tuple(max(radius,min(v,limit-radius))
                     for v,limit in zip(p,(WIDTH_MM,HEIGHT_MM,base)))
        delta = tuple(v-c for v,c in zip(p,core))
        length = math.sqrt(sum(v*v for v in delta))
        return tuple(c+v*radius/length for c,v in zip(core,delta))
    def top(x,y):
        p = rounded(x,y,base)
        encoded_height = values[(ny-1-y)*nx+x]/65535
        height = encoded_height*(RELIEF_MM+BASE_INDENT_DEPTH_MM)-BASE_INDENT_DEPTH_MM
        return (p[0],p[1],p[2]+height)
    def bottom(x,y):
        p = rounded(x,y,0.0)
        gx, depth = groove_point(p[0],p[1])
        return (gx,p[1],max(p[2],depth))
    for y in range(ny-1):
        for x in range(nx-1):
            a,b,c,d = top(x,y),top(x+1,y),top(x+1,y+1),top(x,y+1)
            yield a,b,c
            yield a,c,d
            a,b,c,d = bottom(x,y),bottom(x+1,y),bottom(x+1,y+1),bottom(x,y+1)
            yield a,c,b
            yield a,d,c
    perimeter = ([(x,0) for x in range(nx)] +
                 [(nx-1,y) for y in range(1,ny)] +
                 [(x,ny-1) for x in range(nx-2,-1,-1)] +
                 [(0,y) for y in range(ny-2,0,-1)])
    # Additional side rings sample the round-over smoothly between the grid
    # edges and vertical walls; all boundary vertices are shared exactly.
    rings = [[top(*p) for p in perimeter]]
    for z in (base-radius*.5, base-radius, radius, radius*.5):
        rings.append([rounded(*p,z) for p in perimeter])
    rings.append([bottom(*p) for p in perimeter])
    for upper,lower in zip(rings,rings[1:]):
        for i in range(len(perimeter)):
            j=(i+1)%len(perimeter)
            yield upper[i],lower[i],lower[j]
            yield upper[i],lower[j],upper[j]


def log_mesh_state(logger, body, stage):
    """Read diagnostics defensively across Fusion versions."""
    for label, obj, names in (
        ('body',body,('appearanceSourceType','isClosed','isOriented','isValid')),
        ('display',getattr(body,'displayOverrides',None),
         ('isSuppressFaceGroupColors','isSuppressTriangleEdges')),
        ('displayMesh',getattr(body,'displayMesh',None),
         ('nodeCount','triangleCount'))):
        for name in names:
            try:
                logger.info('%s %s.%s=%s',stage,label,name,getattr(obj,name))
            except Exception as exc:
                logger.info('%s %s.%s unavailable: %s',stage,label,name,exc)


def load_material_colors(nx, ny):
    """Load the audited object-specific map: white, black, brown, red, green."""
    raw = zlib.decompress(base64.b85decode(COLOR_DATA_B85))
    if struct.unpack_from('<II', raw) != (nx, ny) or len(raw) != 8+nx*ny:
        raise ValueError('Color grid does not match relief grid.')
    source_colors = raw[8:]
    if max(source_colors) >= len(COLOR_REMAP):
        raise ValueError('Unknown color material ID.')
    return bytes(COLOR_REMAP[color] for color in source_colors)


def face_material(triangle, colors, nx, ny):
    """Choose a face's palette entry from the aligned material grid."""
    if not all(v[2] > TOTAL_THICKNESS_MM-RELIEF_MM-BASE_EDGE_RADIUS_MM
               for v in triangle):
        return 0
    x = sum(v[0] for v in triangle)/3
    y = sum(v[1] for v in triangle)/3
    ix = min(nx-1,max(0,round(x/WIDTH_MM*(nx-1))))
    iy = min(ny-1,max(0,round((1-y/HEIGHT_MM)*(ny-1))))
    return colors[iy*nx+ix]


def white_foot_appearance(app, design):
    """Native white appearance: feet do not depend on imported STL colors."""
    import adsk.core
    name='White slide-in feet'
    existing=design.appearances.itemByName(name)
    if existing:
        return existing
    library=app.materialLibraries.itemById('BA5EE55E-9982-449B-9D66-9F036540E140')
    seed=library.appearances.itemById('Prism-129') if library else None
    if not seed:
        raise RuntimeError('Fusion generic appearance unavailable for white feet.')
    finish=design.appearances.addByCopy(seed,name)
    for key in ('opaque_albedo','generic_diffuse'):
        prop=adsk.core.ColorProperty.cast(finish.appearanceProperties.itemById(key))
        if prop:
            prop.hasConnectedTexture=False
            prop.value=adsk.core.Color.create(255,255,255,255)
            return finish
    raise RuntimeError('White foot appearance has no editable base color.')


@contextmanager
def preserve_import_colors(app, logger):
    """Disable the default appearance only during import, restoring on error too."""
    preferences=app.preferences.materialPreferences
    previous=preferences.appearanceOverride
    logger.info('Default import appearance override before import: %s',
                previous.name if previous else 'None')
    try:
        preferences.appearanceOverride=None
        logger.info('Default appearance override disabled for color import.')
        yield
    finally:
        preferences.appearanceOverride=previous
        logger.info('Original default appearance override restored.')


def import_colored_mesh(app, component, path, logger):
    import adsk.fusion
    with preserve_import_colors(app,logger):
        return component.meshBodies.add(str(path),adsk.fusion.MeshUnits.MillimeterMeshUnit)


def write_import_mesh(path, records, palette):
    """Create one temporary 3MF directly from (triangle, color-index) records.

    Colors use the same surface-colorgroup representation confirmed in Fusion.
    Face records are spooled to disk to avoid a second full mesh in memory.
    """
    vertices={}
    counts=Counter()
    face_record=struct.Struct('<IIIB')
    with tempfile.TemporaryFile() as faces:
        for triangle,color in records:
            if not 0 <= color < len(palette):
                raise ValueError('Invalid mesh color index.')
            indices=[]
            for vertex in triangle:
                if vertex not in vertices:
                    vertices[vertex]=len(vertices)
                indices.append(vertices[vertex])
            faces.write(face_record.pack(*indices,color))
            counts[color]+=1
        with zipfile.ZipFile(path,'w',zipfile.ZIP_DEFLATED) as archive:
            archive.writestr('[Content_Types].xml',
                '<?xml version="1.0" encoding="UTF-8"?>'
                '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
                '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
                '<Default Extension="model" ContentType="application/vnd.ms-package.3dmanufacturing-3dmodel+xml"/>'
                '</Types>')
            archive.writestr('_rels/.rels',
                '<?xml version="1.0" encoding="UTF-8"?>'
                '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
                '<Relationship Id="rel0" Target="/3D/3dmodel.model" '
                'Type="http://schemas.microsoft.com/3dmanufacturing/2013/01/3dmodel"/>'
                '</Relationships>')
            with archive.open('3D/3dmodel.model','w') as model:
                def emit(text): model.write(text.encode('utf-8'))
                emit('<?xml version="1.0" encoding="UTF-8"?>'
                     '<model unit="millimeter" xml:lang="en-US" '
                     'xmlns="http://schemas.microsoft.com/3dmanufacturing/core/2015/02" '
                     'xmlns:m="http://schemas.microsoft.com/3dmanufacturing/material/2015/02" '
                     'requiredextensions="m"><resources><m:colorgroup id="1">')
                for _,rgb in palette:
                    emit('<m:color color="#'+''.join('%02X'%v for v in rgb)+'FF"/>')
                emit('</m:colorgroup><object id="2" type="model" pid="1" pindex="0">'
                     '<mesh><vertices>')
                for v in vertices:
                    emit('<vertex x="%.8f" y="%.8f" z="%.8f"/>'%v)
                emit('</vertices><triangles>')
                faces.seek(0)
                while True:
                    data=faces.read(face_record.size)
                    if not data: break
                    a,b,c,color=face_record.unpack(data)
                    emit('<triangle v1="%d" v2="%d" v3="%d" pid="1" '
                         'p1="%d" p2="%d" p3="%d"/>'%(a,b,c,color,color,color))
                emit('</triangles></mesh></object></resources>'
                     '<build><item objectid="2"/></build></model>')
    return {'vertices':len(vertices),'triangles':sum(counts.values()),
            'color_faces':{palette[i][0]:n for i,n in sorted(counts.items())}}


def configure_display(body):
    body.displayOverrides.isSuppressFaceGroupColors=True
    body.displayOverrides.isSuppressTriangleEdges=True


def run(context):
    import adsk.core
    import adsk.fusion
    app=adsk.core.Application.get()
    logger=logging.getLogger('CamelandPanda')
    logger.setLevel(logging.INFO)
    logger.propagate=False
    for old in list(logger.handlers):
        logger.removeHandler(old)
        old.close()
    handler=None
    started=time.monotonic()
    try:
        handler=logging.FileHandler(LOG_PATH,encoding='utf-8')
        formatter=logging.Formatter('%(asctime)sZ %(levelname)s %(message)s')
        formatter.converter=time.gmtime
        handler.setFormatter(formatter)
        logger.addHandler(handler)
        logger.info('=== single-script-v1 RUN START; Fusion=%s ===',app.version)
        logger.info('Dimensions=%s mm; relief=%s; radius=%s; stand=%s degrees',
                    (WIDTH_MM,HEIGHT_MM,TOTAL_THICKNESS_MM),RELIEF_MM,BASE_EDGE_RADIUS_MM,ANGLE_DEG)
        if not 0 < RELIEF_MM < TOTAL_THICKNESS_MM:
            raise ValueError('Relief must be positive and less than total thickness.')
        nx,ny,heights=load_heights()
        colors=load_material_colors(nx,ny)
        with tempfile.TemporaryDirectory(prefix='CamelandPanda-') as directory:
            directory=Path(directory)
            plaque_path=directory/'plaque.3mf'
            records=((t,face_material(t,colors,nx,ny)) for t in mesh_triangles(nx,ny,heights))
            stats=write_import_mesh(plaque_path,records,PALETTE)
            if set(stats['color_faces']) != {name for name,_ in PALETTE}:
                raise ValueError('Generated plaque is missing a palette color.')
            logger.info('Temporary plaque mesh: %s; color map=%s',stats,COLOR_MAP_REVISION)
            doc=app.documents.add(adsk.core.DocumentTypes.FusionDesignDocumentType)
            doc.name='Camel and Panda'
            design=adsk.fusion.Design.cast(app.activeProduct)
            if not design: raise RuntimeError('New Fusion design unavailable.')
            design.designType=adsk.fusion.DesignTypes.DirectDesignType
            design.unitsManager.distanceDisplayUnits=adsk.fusion.DistanceUnits.MillimeterDistanceUnits
            bodies=import_colored_mesh(app,design.rootComponent,plaque_path,logger)
            if not bodies or bodies.count!=1: raise RuntimeError('Plaque import failed.')
            body=bodies.item(0)
            body.name='Plaque - Save as Mesh - 3MF'
            body.appearance=None
            configure_display(body)
            log_mesh_state(logger,body,'Plaque imported')
            design.rootComponent.attributes.add('CamelandPanda','dimensions_mm',
                '{} x {} x {}'.format(WIDTH_MM,HEIGHT_MM,TOTAL_THICKNESS_MM))
            finish=white_foot_appearance(app,design)
            for number,center in enumerate(CHANNEL_CENTERS,1):
                foot_path=directory/('foot-%d.3mf'%number)
                triangles=foot_triangles(center,TOTAL_THICKNESS_MM-RELIEF_MM,BASE_EDGE_RADIUS_MM)
                stats=write_import_mesh(foot_path,((t,0) for t in triangles),[PALETTE[0]])
                feet=import_colored_mesh(app,design.rootComponent,foot_path,logger)
                if not feet or feet.count!=1: raise RuntimeError('Foot import failed.')
                foot=feet.item(0)
                foot.name='White foot %d - Save as Mesh - 3MF'%number
                foot.appearance=finish
                configure_display(foot)
                logger.info('White rear foot %d imported: %s',number,stats)
        logger.info('Temporary import files removed. No automatic exports created.')
        app.activeViewport.fit()
        app.activeViewport.refresh()
        app.userInterface.messageBox(
            'Created the colored plaque and two white rear feet.\n\n'
            'Save the design in Fusion. To export each body, right-click it and choose\n'
            'Save as Mesh > 3MF > Millimeter. STL does not retain colors.\n\n'
            'Log: '+str(LOG_PATH))
    except Exception:
        logger.error('Creation failed:\n%s',traceback.format_exc())
        app.userInterface.messageBox('Plaque creation failed:\n'+traceback.format_exc()+
                                     '\nLog: '+str(LOG_PATH))
    finally:
        if handler:
            logger.info('RUN END elapsed=%.2fs',time.monotonic()-started)
            handler.flush()
            logger.removeHandler(handler)
            handler.close()


